const event = $json.body?.event || {};

// 1. Zdefiniuj ID swojego bota ze Slacka (znajdziesz je w Slacku lub payloadzie webhooka)
const MY_BOT_USER_ID = 'YOUR_BOT_USER_ID'; // Zamień na ID swojego bota (np. U07ABC123)

// 2. Jeśli autorem jest bot, wiadomość pochodzi od bota LUB autor to Twój bot -> ODRZUĆ
if (!event.user || event.bot_id || event.user === MY_BOT_USER_ID) {
  return []; // Zatrzymuje workflow (brak wyjścia do AI Agenta)
}

// 3. Blokada powtórzeń ze Slacka (retry) na podstawie event_id
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedEvents) {
  staticData.processedEvents = [];
}

const eventId = $json.body?.event_id;

if (eventId && staticData.processedEvents.includes(eventId)) {
  return []; // Odrzuca zduplikowane requesty Slacka
}

if (eventId) {
  staticData.processedEvents.push(eventId);
  if (staticData.processedEvents.length > 100) {
    staticData.processedEvents.shift();
  }
}

// 4. Jeśli pisał człowiek – przekaż dane do AI Agenta
return [$input.item];
